{
  "findings": [
    {
      "check_id": "CKV_AZURE_1",
      "title": "Ensure HTTPS Only Traffic is Enabled for Storage Accounts",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "HIGH",
      "explanation": "The storage account allows HTTP traffic because 'enable_https_traffic_only' is set to false. This exposes data in transit to potential interception or man-in-the-middle attacks, violating security best practices for Azure Storage."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account\" \"notification_storage\" {\n  name                     = \"smartgridscada${random_string.suffix.result}\"\n  resource_group_name      = azurerm_resource_group.smart_grid_rg.name\n  location                 = azurerm_resource_group.smart_grid_rg.location\n  account_tier             = \"Standard\"\n  account_replication_type = \"LRS\"\n  enable_https_traffic_only = true\n}",
  "fix_summary": "Changed 'enable_https_traffic_only' from false to true to enforce secure HTTPS-only communication for the storage account."
}
